/**
 * Retorna, para cada ambiente cadastrado, a situação dos 14 horários do dia e a contagem de horários livres. Alimenta a mini-agenda dos cards da tela Ambientes.
 * @summary Agenda de todos os ambientes
 */
export const availabilityForAll = (
  params?: AvailabilityForAllParams,
  signal?: AbortSignal,
) => {
  return api<EnvironmentAvailabilityResponse[]>({
    url: `/reserves/availability`,
    method: "GET",
    params,
    signal,
  });
};

export const getAvailabilityForAllQueryKey = (
  params?: AvailabilityForAllParams,
) => {
  return [`/reserves/availability`, ...(params ? [params] : [])] as const;
};

