/**
 * Remove uma reserva. O solicitante pode cancelar as próprias reservas; ADMIN e OWNER podem cancelar a de qualquer pessoa.
 * @summary Cancelar reserva
 */
export const cancel = (reserveId: string, signal?: AbortSignal) => {
  return api<void>({ url: `/reserves/${reserveId}`, method: "DELETE", signal });
};

export const getCancelMutationOptions = <
  TError = ErrorType<void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof cancel>>,
    TError,
    { reserveId: string },
    TContext
  >;
}): UseMutationOptions<
  Awaited<ReturnType<typeof cancel>>,
  TError,
  { reserveId: string },
  TContext
> => {
  const mutationKey = ["cancel"];
  const { mutation: mutationOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey } };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof cancel>>,
    { reserveId: string }
  > = (props) => {
    const { reserveId } = props ?? {};

    return cancel(reserveId);
  };

  return { mutationFn, ...mutationOptions };
};

export type CancelMutationResult = NonNullable<
  Awaited<ReturnType<typeof cancel>>
>;

export type CancelMutationError = ErrorType<void>;

/**
 * @summary Cancelar reserva
 */
export const useCancel = <TError = ErrorType<void>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof cancel>>,
      TError,
      { reserveId: string },
      TContext
    >;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof cancel>>,
  TError,
  { reserveId: string },
  TContext
> => {
  return useMutation(getCancelMutationOptions(options), queryClient);
};
